{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table hox_db.maplemonk.HOX_yfl_sevenchef_Tax_consolidated_report_intermediate as with sku_marketplace as ( select * from ( select replace(marketplace_sku,\'\`\',\'\') marketplace_sku ,replace(master_sku,\'\`\',\'\') master_sku ,row_number() over (partition by replace(marketplace_sku,\'\`\',\'\'), replace(master_sku,\'\`\',\'\') order by 1) rw from HOX_DB.MAPLEMONK.sku_master ) where rw=1 ), abc as ( select a.report_type, a.brand, a.Reference_Code, a.Order_status, a.invoice_status, a.order_type, case when a.fulfillment_channel = \'AFN\' then \'Amazon FBA\' when a.fulfillment_channel = \'MFN\' then \'Amazon EasyShip\' else fulfillment_channel end as fulfillment_channel, date(a.report_date) as report_date, a.SKU, sum(case when coalesce(a.Quantity,0) = 0 then 1 else coalesce(a.Quantity,0) end) as QUANTITY, sum(coalesce(a.Invoice_amount,0)) as Invoice_amt, sum(coalesce(a.absolute_invoice_amount,0)) as absolute_invoice_amount, sum(coalesce(a.Tax_exclusive_gross,0))as Tax_exclusive_gross , sum(abs(coalesce(a.Tax_exclusive_gross,0))) as abs_Tax_exclusive_gross , sum(coalesce(a.Total_tax_amount,0)) as Total_tax_amount from HOX_DB.MapleMonk.HOX_yfl_SevenChef_Amazon_Tax_Fact_Items a group by 1,2,3,4,5,6,7,8,9 ), base as ( select a.report_type, a.Reference_Code, a.Order_status, a.invoice_status, a.order_type, a.brand, date(a.report_date) as report_date, coalesce(c.master_sku, a.SKU) as sku, lower(coalesce(b.marketplace, case when lower(a.sku) like \'%es\' then \'Amazon EasyShip\' when lower(a.fulfillment_channel) is null then \'Amazon FBA\' when lower(a.fulfillment_channel) = \'\' then \'Amazon FBA\' else a.fulfillment_channel end)) as marketplace, sum(a.Quantity) as QUANTITY, sum(a.Invoice_amt) as Invoice_amt, sum(a.absolute_invoice_amount) as Selling_price, sum(a.absolute_invoice_amount) as absolute_invoice_amount, sum(a.Tax_exclusive_gross)as Tax_exclusive_gross , sum(a.abs_Tax_exclusive_gross) as abs_Tax_exclusive_gross, sum(a.Total_tax_amount) as Total_tax_amount From abc a left join ( select order_id, case when lower(source) = \'amazon\' then \'Amazon FBA\' else \'Amazon EasyShip\' end as marketplace from HOX_DB.MAPLEMONK.HOX_DB_YFLHome_amazon_fact_items group by 1,2 )b on a.Reference_Code = b.order_id left join sku_marketplace c on lower(a.sku) = lower(c.marketplace_sku) group by 1,2,3,4,5,6,7,8,9 ), sku_price_cancel as ( select distinct SKU, date_trunc(\'month\', report_date :: date) as report_month, brand, round(avg(ABSOLUTE_INVOICE_AMOUNT/ quantity),2) as avg_sale_price, round(avg(abs_Tax_exclusive_gross/ quantity),2) as avg_abs_Tax_exclusive_gross from base where lower(ORDER_STATUS) = \'shipment\' group by 1,2,3 order by 1,2,3 ), sku_price_cancel_overall as ( select SKU, brand, round(avg(ABSOLUTE_INVOICE_AMOUNT/ quantity),2) as avg_sale_price, round(avg(abs_Tax_exclusive_gross/ quantity),2) as avg_abs_Tax_exclusive_gross from base where lower(ORDER_STATUS) = \'shipment\' group by 1,2 order by 1,2 ), sale_data as ( select distinct a.report_type, null as Company_Name, null as seller_gst, a.marketplace, a.Reference_Code, a.order_type, a.Order_status, a.invoice_status, a.report_date, a.SKU, a.brand, a.QUANTITY, case when lower(a.Order_status) like \'cancel%\' then coalesce((a.quantity * b.avg_sale_price), (a.quantity * c.avg_sale_price)) else Invoice_amt end as Invoice_amt, case when lower(a.Order_status) like \'cancel%\' then coalesce((a.quantity * b.avg_sale_price), (a.quantity * c.avg_sale_price)) else Selling_price end as Selling_price, case when lower(a.Order_status) like \'cancel%\' then coalesce((a.quantity * b.avg_sale_price), (a.quantity * c.avg_sale_price)) else absolute_invoice_amount end as absolute_invoice_amount, case when lower(a.Order_status) like \'cancel%\' then coalesce((a.quantity * b.avg_abs_Tax_exclusive_gross), (a.quantity * c.avg_abs_Tax_exclusive_gross)) else Tax_exclusive_gross end as Tax_exclusive_gross, case when lower(a.Order_status) like \'cancel%\' then coalesce((a.quantity * b.avg_abs_Tax_exclusive_gross), (a.quantity * c.avg_abs_Tax_exclusive_gross)) else abs_Tax_exclusive_gross end as abs_Tax_exclusive_gross, Total_tax_amount from base a left join sku_price_cancel b on lower(a.sku) = lower(b.sku) and date_trunc(\'month\', a.report_date :: date) = b.report_month and lower(a.brand) = lower(b.brand) left join sku_price_cancel_overall c on lower(a.sku) = lower(c.sku) and lower(a.brand) = lower(c.brand) ), easyecom_tax as ( select REPORT_TYPE , COMPANY_NAME , SELLER_GST , lower(marketplace) as marketplace , REFERENCE_CODE , ORDER_TYPE , ORDER_STATUS , INVOICE_STATUS , date(REPORT_DATE) as REPORT_DATE , SKU , brand , QUANTITY , INVOICE_AMOUNT , SELLING_PRICE , ABSOLUTE_INVOICE_AMOUNT , TAX_EXCLUSIVE_GROSS , abs_Tax_exclusive_gross , TOTAL_TAX_AMOUNT from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items ), cogs as ( select distinct sku, (cost:: float) as cost, WEIGHT from HOX_DB.MAPLEMONK.easyecom_yflhome_product_master union select distinct MODEL_NO, (cost:: float) as cost, WEIGHT from HOX_DB.MAPLEMONK.easyecom_yflhome_product_master ), spends_data as ( select date as ads_date, case when lower(marketplace) like \'%shopify%\' then \'shopify\' when lower(marketplace) like \'%flipkart%\' then \'flipkart\' when lower(marketplace) like \'%amazon%\' then \'amazon fba\' else lower(marketplace) end as marketplace, round(sum(marketing_spend),2) as spend from HOX_DB.MAPLEMONK.HOX_DB_YFLHOME_SALES_COST_SOURCE group by 1,2 having sum(marketing_spend) > 0 order by 1,2 ), final_result as ( Select distinct o.*, a.weight, (a.weight * quantity) as total_weight , case when o.sku = \'YFLMRGBLPRD2\' and REPORT_DATE >= \'2024-12-20\' then 4148 else a.cost end as cost, case when o.sku = \'YFLMRGBLPRD2\' and REPORT_DATE >= \'2024-12-20\' then (4148 * QUANTITY) else (QUANTITY * a.cost) end as COGS FROM ( select *, date(date_trunc(\'month\', REPORT_DATE)) as report_month, date(date_trunc( \'week\', REPORT_DATE)) as report_week from sale_data union select *, date(date_trunc(\'month\', REPORT_DATE)) as report_month, date(date_trunc( \'week\', REPORT_DATE)) as report_week from easyecom_tax )o left join cogs a on lower(o.sku) = lower(a.SKU) ), SAAS_price as ( select REFERENCE_CODE, MARKETPLACE, \'easyecom sale\' as REPORT_TYPE, REPORT_DATE, sum(easyecom_cost)as EASYECOM_COST, sum(interakt_cost) as Interakt_cost, sum(clickpost_cost) as clickpost_Cost from hox_db.maplemonk.HOX_yfl_sevenchef_SAAS_cost group by 1,2,3,4 order by 1,2,4 ) select a.REPORT_TYPE , a.COMPANY_NAME , a.SELLER_GST , trim(coalesce(a.MARKETPLACE, b.MARKETPLACE)) as MARKETPLACE , a.REFERENCE_CODE , a.ORDER_TYPE , a.ORDER_STATUS , a.INVOICE_STATUS , coalesce(date(a.REPORT_DATE), ads_date) as REPORT_DATE , a.QUANTITY , a.SKU , a.brand , a.INVOICE_AMT , a.SELLING_PRICE , a.ABSOLUTE_INVOICE_AMOUNT , a.TAX_EXCLUSIVE_GROSS , a.abs_Tax_exclusive_gross , a.TOTAL_TAX_AMOUNT , coalesce(a.report_month, date(date_trunc(\'month\', ads_date))) as report_month , coalesce(a.report_week, date(date_trunc(\'week\', ads_date))) as report_week , a.cost , a.COGS , a.weight , a.total_weight , div0(spend, count(1) over (partition by coalesce(a.MARKETPLACE, b.MARKETPLACE), coalesce(date(a.REPORT_DATE), ads_date) order by 1)) as final_spend , case when a.sku in (\'BLKBE100\',\'BLKEE100\',\'BLKINOD100\',\'BLKLD100\',\'BLKODMY100\',\'BLKSS100\',\'DAWN\', \'DUSK\') then \'100 ml\' when a.sku in (\'BLKBE20\',\'BLKEE20\',\'BLKINOD20\',\'BLKLD20\',\'BLKODMY20\',\'BLKSS20\',\'BLKDN20\', \'BLKDK20\') then \'20 ml\' when a.sku in (\'BLKBE8\',\'BLKEE8\',\'BLKINOD8\',\'BLKLD8\',\'BLKODMY8\',\'BLKSS8\',\'BLKDN8\', \'BLKDK8\') then \'8 ml\' when a.sku in (\'BLKPRMNCN-P4_20\', \'BLKRLCN-P4_20\') then \'Pack of 4 - 20 ml\' when a.sku in (\'BLKCN-8_8\') then \'Pack of 8 - 8 ml\' when a.sku in (\'BLKCAP_FR_01\', \'BLKFREECAP_01\') then \'CAP\' when a.sku in (\'BL_FREE_TSHIRT_01\') then \'Tshirt\' end as sku_type, div0(EASYECOM_COST, count(1) over (partition by a.Reference_Code, a.report_type, a.MARKETPLACE, a.REPORT_DATE order by 1)) as EASYECOM_COST, div0(INTERAKT_COST, count(1) over (partition by a.Reference_Code, a.report_type, a.MARKETPLACE, a.REPORT_DATE order by 1)) as INTERAKT_COST, div0(CLICKPOST_COST, count(1) over (partition by a.Reference_Code, a.report_type, a.MARKETPLACE, a.REPORT_DATE order by 1)) as CLICKPOST_COST from final_result a full outer join spends_data b on a.report_date = b.ads_date and lower(a.marketplace) = lower(b.marketplace) left join SAAS_price c on a.REFERENCE_CODE = c.REFERENCE_CODE and lower(a.report_type) = lower(c.report_type) and lower(a.MARKETPLACE) = lower(c.MARKETPLACE) and a.REPORT_DATE = c.report_date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            